(927333, 107096, 9089, '<td valign="top">Interesting use of push processing.  I like the crop, leaves me wondering what is going on.</td>', 'Interesting use of push processing.  I like the crop, leaves me wondering what is going on.', '2004-09-27 02:13:12.000000', NULL, 1),
(927334, 108101, 5792, '<td valign="top">Wonderful, wonderful detail. Exceptionally high quality image.</td>', 'Wonderful, wonderful detail. Exceptionally high quality image.', '2004-09-27 02:13:52.000000', NULL, 1),
(927340, 107471, 9089, '<td valign="top">Complicated fear?  I''m trying to see the connection...  I would prefer for the bridge not to be in shadows, so a shot from the other side to the left, with the sun shining on the bridge would have been better to highlight the bridge, or come back at another time of day.</td>', 'Complicated fear?  I''m trying to see the connection...  I would prefer for the bridge not to be in shadows, so a shot from the other side to the left, with the sun shining on the bridge would have been better to highlight the bridge, or come back at another time of day.', '2004-09-27 02:17:22.000000', NULL, 1),
(927342, 107893, 17103, '<td valign="top">Wow, very nice!  Great subject for the challenge, beautiful composition and lighting.</td>', 'Wow, very nice!  Great subject for the challenge, beautiful composition and lighting.', '2004-09-27 02:18:50.000000', NULL, 1),
(927345, 108100, 9089, '<td valign="top">Good eye, good composition, I''ll be on the lookout now for similar photos to take.  What hurts the picture though is the blurriness of the central dividing line created by the edge of the ''intricate'' building.  If it had been razor sharp would make the photo really pop.</td>', 'Good eye, good composition, I''ll be on the lookout now for similar photos to take.  What hurts the picture though is the blurriness of the central dividing line created by the edge of the ''intricate'' building.  If it had been razor sharp would make the photo really pop.', '2004-09-27 02:19:27.000000', NULL, 1),
(927351, 108078, 23478, '<td valign="top">Excelllent photo, the only drawback is that the background would be much better as a solid color.</td>', 'Excelllent photo, the only drawback is that the background would be much better as a solid color.', '2004-09-27 02:23:40.000000', NULL, 1),
(927353, 107780, 23478, '<td valign="top">Great photo.</td>', 'Great photo.', '2004-09-27 02:24:03.000000', NULL, 1),
