(927355, 108101, 23478, '<td valign="top">Wonderful job capturing the intricate architecture.</td>', 'Wonderful job capturing the intricate architecture.', '2004-09-27 02:26:52.000000', NULL, 1),
(927358, 107960, 23478, '<td valign="top">I Think it  would have been more effective to crop off the right half of the photo.</td>', 'I Think it  would have been more effective to crop off the right half of the photo.', '2004-09-27 02:28:24.000000', NULL, 1),
(927359, 107519, 23478, '<td valign="top">This is just superb!</td>', 'This is just superb!', '2004-09-27 02:28:58.000000', NULL, 1),
