(928593, 107691, 25464, '<td valign="top">Bumping up to an 8.  Complex in both subject and appearance.  Good job.</td>', 'Bumping up to an 8.  Complex in both subject and appearance.  Good job.', '2004-09-27 22:37:47.000000', NULL, 1),
(928601, 107856, 20941, '<td valign="top">very interesting subject...certainly meets the criteria of the challenge. I''m not sure what it is exactly.</td>', 'very interesting subject...certainly meets the criteria of the challenge. I''m not sure what it is exactly.', '2004-09-27 22:45:47.000000', NULL, 1),
(928605, 106581, 20941, '<td valign="top">like the composition exept the tree to the left bordering his face. definatly complex and a cool subject. nice</td>', 'like the composition exept the tree to the left bordering his face. definatly complex and a cool subject. nice', '2004-09-27 22:50:53.000000', NULL, 1),
(928608, 107338, 20941, '<td valign="top">complex and nicely done i like it.</td>', 'complex and nicely done i like it.', '2004-09-27 22:52:55.000000', NULL, 1),
(928609, 107331, 20941, '<td valign="top">great portrait shot</td>', 'great portrait shot', '2004-09-27 22:53:53.000000', NULL, 1),
(928611, 108100, 20941, '<td valign="top">love how you composed this making it more complex, great idea, nicely done IMHO!</td>', 'love how you composed this making it more complex, great idea, nicely done IMHO!', '2004-09-27 22:55:11.000000', NULL, 1),
(928614, 107458, 25464, '<td valign="top">This is an interesting angle.  The focus is a bit soft and the lense flare is obvious; however, I think it works for this shot.  Others may not agree, but I like it. 7.</td>', 'This is an interesting angle.  The focus is a bit soft and the lense flare is obvious; however, I think it works for this shot.  Others may not agree, but I like it. 7.', '2004-09-27 22:58:41.000000', NULL, 1),
(928615, 107909, 25464, '<td valign="top">A well taken shot and an interesting complex subject.  I think the centered composition is a bit boring here combined with the flat white background.  Overall good shot. 7.</td>', 'A well taken shot and an interesting complex subject.  I think the centered composition is a bit boring here combined with the flat white background.  Overall good shot. 7.', '2004-09-27 23:00:14.000000', NULL, 1),
(928616, 108099, 25464, '<td valign="top">Well taken.  Complex subject on a complex pattern background.  A win.  Bumping up to 8.</td>', 'Well taken.  Complex subject on a complex pattern background.  A win.  Bumping up to 8.', '2004-09-27 23:01:11.000000', NULL, 1),
(928619, 107386, 25464, '<td valign="top">This definitely has complexity; however, I dont find much asthetic value.  I think I might have liked this one better in color.  Good angle.</td>', 'This definitely has complexity; however, I dont find much asthetic value.  I think I might have liked this one better in color.  Good angle.', '2004-09-27 23:03:02.000000', NULL, 1),
(928620, 107753, 25464, '<td valign="top">This was a excellent idea.  I think I would have chosen a colored background rather than the stark white.  Points for creativity though.</td>', 'This was a excellent idea.  I think I would have chosen a colored background rather than the stark white.  Points for creativity though.', '2004-09-27 23:04:06.000000', NULL, 1),
(928621, 107193, 25754, '<td valign="top">Interesting abstract photo. I like the selective focusing towards the back. I just wish I knew what this instrument was :)</td>', 'Interesting abstract photo. I like the selective focusing towards the back. I just wish I knew what this instrument was :)', '2004-09-27 23:04:40.000000', NULL, 1),
(928622, 108078, 25464, '<td valign="top">Interesting use of the background.</td>', 'Interesting use of the background.', '2004-09-27 23:04:41.000000', NULL, 1),
(928625, 107829, 25464, '<td valign="top">Nice approach.  Dramatic lighting.  Good job.</td>', 'Nice approach.  Dramatic lighting.  Good job.', '2004-09-27 23:05:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(928627, 107763, 25464, '<td valign="top">I think I would have liked to see just the seeds.  Composition is a bit wierd for me.</td>', 'I think I would have liked to see just the seeds.  Composition is a bit wierd for me.', '2004-09-27 23:06:44.000000', NULL, 1),
(928629, 107260, 20941, '<td valign="top">beautiful colors kinda surreal looking. the leaves and limbs on the right kinda interfere with the flow for me. Interesting subject to convey compexity but post processing seems to have made your point.</td>', 'beautiful colors kinda surreal looking. the leaves and limbs on the right kinda interfere with the flow for me. Interesting subject to convey compexity but post processing seems to have made your point.', '2004-09-27 23:07:10.000000', NULL, 1),
(928634, 107623, 20941, '<td valign="top">beautifully done!</td>', 'beautifully done!', '2004-09-27 23:10:26.000000', NULL, 1),
(928638, 107694, 25754, '<td valign="top">This tree definitely looks complex, but I think it would have been better if you cropped the image so that the tree is the main subject. As it is now, the background is too distracting. Punchier colours would help as well.</td>', 'This tree definitely looks complex, but I think it would have been better if you cropped the image so that the tree is the main subject. As it is now, the background is too distracting. Punchier colours would help as well.', '2004-09-27 23:12:57.000000', NULL, 1),
(928659, 108027, 25464, '<td valign="top">This photo is a beatiful abstract piece of art in my opinion.  That said, this really says simplicity to me more than complexity.  I think it is great work, and I could definitely see this on my livingroom wall.  Good job.</td>', 'This photo is a beatiful abstract piece of art in my opinion.  That said, this really says simplicity to me more than complexity.  I think it is great work, and I could definitely see this on my livingroom wall.  Good job.', '2004-09-27 23:42:29.000000', NULL, 1),
(928665, 108027, 10080, '<td valign="top">I really like this one! Great color design and feeling</td>', 'I really like this one! Great color design and feeling', '2004-09-27 23:50:14.000000', NULL, 1),
(928673, 108018, 10080, '<td valign="top">very nice colors and depth! Design is great! My best score yet!</td>', 'very nice colors and depth! Design is great! My best score yet!', '2004-09-27 23:55:22.000000', NULL, 1),
