(933038, 107483, 24613, '<td valign="top">This sure is complex.  Nice shot!</td>', 'This sure is complex.  Nice shot!', '2004-09-30 17:45:59.000000', NULL, 1),
(933039, 108023, 24613, '<td valign="top">Very beautiful shot.  More calming than complex.  Great work though!</td>', 'Very beautiful shot.  More calming than complex.  Great work though!', '2004-09-30 17:46:49.000000', NULL, 1),
(933098, 107966, 21890, '<td valign="top">It is infact complex. well done!</td>', 'It is infact complex. well done!', '2004-09-30 18:15:33.000000', NULL, 1),
(933155, 108018, 22046, '<td valign="top">I like the colors in this and the complex patterns. I''d like to see a deeper depth of field. I think that would make it even better.</td>', 'I like the colors in this and the complex patterns. I''d like to see a deeper depth of field. I think that would make it even better.', '2004-09-30 19:28:58.000000', NULL, 1),
(933251, 107287, 15207, '<td valign="top">This is such a great subject. If you ever get the chance to shoot again, you may find adding a bit of negative(empty) space to the left side will add to the pic - and give a sense of movement/potential movment that the dog is going to ride away. but keep the angle - it''s perfect. Also, it seems a bit dark on my monitor. Dusk/Dawn is a great time to shoot- but sometimes if it''s cloudy you need a bit more light. the details are just a bit lost in the dog, but I totally understand since you have to shrink these photos so small for challenges. Ihope you do well.</td>', 'This is such a great subject. If you ever get the chance to shoot again, you may find adding a bit of negative(empty) space to the left side will add to the pic - and give a sense of movement/potential movment that the dog is going to ride away. but keep the angle - it''s perfect. Also, it seems a bit dark on my monitor. Dusk/Dawn is a great time to shoot- but sometimes if it''s cloudy you need a bit more light. the details are just a bit lost in the dog, but I totally understand since you have to shrink these photos so small for challenges. Ihope you do well.', '2004-09-30 20:51:10.000000', NULL, 1),
(933288, 108103, 19248, '<td valign="top">Cool idea, too bad it is so blurred</td>', 'Cool idea, too bad it is so blurred', '2004-09-30 21:38:59.000000', NULL, 1),
(933366, 107895, 25347, '<td valign="top">Viva Venezuela!  I love this shot.  There are so many drops of varying shapes that it adds to the wonderful composition.  Good job, I hope this does well.</td>', 'Viva Venezuela!  I love this shot.  There are so many drops of varying shapes that it adds to the wonderful composition.  Good job, I hope this does well.', '2004-09-30 23:29:48.000000', NULL, 1),
(933445, 108102, 22748, '<td valign="top">I''m _definitely_not_ a fan of the on-camera flash. Such yucky lighting it provides. With natural light, though, this shot would be pretty cool.</td>', 'I''m _definitely_not_ a fan of the on-camera flash. Such yucky lighting it provides. With natural light, though, this shot would be pretty cool.', '2004-10-01 00:59:53.000000', NULL, 1),
(933619, 107923, 22748, '<td valign="top">Yet another picture that appears to have the dreaded flash-flood problem. The on-camera flash really ruins a lot of great pictures. Colors and textures are ruined by it.</td>', 'Yet another picture that appears to have the dreaded flash-flood problem. The on-camera flash really ruins a lot of great pictures. Colors and textures are ruined by it.', '2004-10-01 02:22:24.000000', NULL, 1),
(933805, 108106, 22748, '<td valign="top">This is the best circuit board picture I''ve seen. I like the lighting and the background. Nice.</td>', 'This is the best circuit board picture I''ve seen. I like the lighting and the background. Nice.', '2004-10-01 03:45:16.000000', NULL, 1),
(933826, 107909, 22046, '<td valign="top">This makes me think of a sculpture by MC Escher. Love the colors. Did you do the folding too? (Don''t answer now... but after the voting is over I''m curious.) Excellent work.</td>', 'This makes me think of a sculpture by MC Escher. Love the colors. Did you do the folding too? (Don''t answer now... but after the voting is over I''m curious.) Excellent work.', '2004-10-01 04:01:59.000000', NULL, 1),
