(936774, 107467, 21714, '<td valign="top">I like the angle you have shot this from. It shows a lot fo depth in the tracks. And the colours really bring out the image. A bit unsure about the top left corner though. I think it would be worth a try to crop and take out wee bit from the top. 9</td>', 'I like the angle you have shot this from. It shows a lot fo depth in the tracks. And the colours really bring out the image. A bit unsure about the top left corner though. I think it would be worth a try to crop and take out wee bit from the top. 9', '2004-10-02 12:10:40.000000', NULL, 1),
(936776, 107214, 27524, '<td valign="top">Well done... lights, focus, colors.</td>', 'Well done... lights, focus, colors.', '2004-10-02 12:10:51.000000', NULL, 1),
(936778, 108071, 27524, '<td valign="top">Good background and colors... real tasteful.</td>', 'Good background and colors... real tasteful.', '2004-10-02 12:12:44.000000', NULL, 1),
