(937308, 107895, 20364, '<td valign="top">Fantastic subject.  I love the effect.  I gave this a 10.  My only one of the challenge.</td>', 'Fantastic subject.  I love the effect.  I gave this a 10.  My only one of the challenge.', '2004-10-02 16:50:05.000000', NULL, 1),
