(937649, 107390, 23338, '<td valign="top">Now if only the little wooden model was sodering connections, THEN I might sit up and take notice.  As it is, I can only assume he was just tossed into the picture.  Makes no sense at all.  Just the same, it IS a good image of the electronic boards.</td>', 'Now if only the little wooden model was sodering connections, THEN I might sit up and take notice.  As it is, I can only assume he was just tossed into the picture.  Makes no sense at all.  Just the same, it IS a good image of the electronic boards.', '2004-10-02 21:19:06.000000', NULL, 1),
(937661, 108023, 13091, '<td valign="top">A slight rotation would have improved it IMHO. Still good though. 7</td>', 'A slight rotation would have improved it IMHO. Still good though. 7', '2004-10-02 21:24:27.000000', NULL, 1),
(937668, 107950, 23338, '<td valign="top">Most accurate title in challenge.  :-)  Nicely posed by models.   I really puzzled over the composition/cropping though.  My personal preference would have been either to crop much closer (right under shirt and just to the left of female model) in order to emphasize their feelings, or left more above the guy''s head and to HIS left in order to more center the action.  Anyway, good luck in the challenge.</td>', 'Most accurate title in challenge.  :-)  Nicely posed by models.   I really puzzled over the composition/cropping though.  My personal preference would have been either to crop much closer (right under shirt and just to the left of female model) in order to emphasize their feelings, or left more above the guy''s head and to HIS left in order to more center the action.  Anyway, good luck in the challenge.', '2004-10-02 21:26:20.000000', NULL, 1),
(937677, 107574, 23338, '<td valign="top">1.  I love black and white.  2.  I love chaos in nature.  3.  I love really neat contrast.  Thus, you get rated really high.   Might have been higher, but appears kind of soft.  Good luck in the challenge.</td>', '1.  I love black and white.  2.  I love chaos in nature.  3.  I love really neat contrast.  Thus, you get rated really high.   Might have been higher, but appears kind of soft.  Good luck in the challenge.', '2004-10-02 21:32:44.000000', NULL, 1),
(937680, 107965, 23338, '<td valign="top">Nice tone, composition, definition and contrasts.  Definitely embodies complexity.</td>', 'Nice tone, composition, definition and contrasts.  Definitely embodies complexity.', '2004-10-02 21:34:00.000000', NULL, 1),
(937735, 108069, 1031, '<td valign="top">I really like the way you used her hair.</td>', 'I really like the way you used her hair.', '2004-10-02 22:44:21.000000', NULL, 1),
