INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(941735, 106529, 22748, '<td valign="top">Okay, I''ve got to hand it to you, this is a fabulous photograph, even though I was not impressed by it during voting. It really looks like you simply took a picture of a page in a book. That''s amazing and difficult to achieve, but it also still doesn''t provide any indication to me that you really created it "from scratch". Just my feelings about this image, I know most people differ.</td>', 'Okay, I''ve got to hand it to you, this is a fabulous photograph, even though I was not impressed by it during voting. It really looks like you simply took a picture of a page in a book. That''s amazing and difficult to achieve, but it also still doesn''t provide any indication to me that you really created it "from scratch". Just my feelings about this image, I know most people differ.', '2004-10-04 19:59:17.000000', NULL, 0),
